#!/bin/bash
# Generated by brain.deployment.chaos.render_chaos. Do not edit: edit the table of faults
# and regenerate, or this script and the table disagree and the table is the tested one.
# Stops one component of a running install at a time, reads what the application does
# while it is down and whether it recovers, and starts it again. Run it only on an
# install that may be broken on purpose.
set -uo pipefail

BRAIN_HOME="${BRAIN_HOME:-/opt/brain}"
POLL_SECONDS="${BRAIN_CHAOS_POLL_SECONDS:-5}"
BRAIN_PROFILE=""
RECOVER_WITHIN=180
DOWN_WAIT="${BRAIN_CHAOS_DOWN_WAIT:-30}"
DISPOSABLE=no
WANTED=""
CURRENT_IDS=""
ran=0; passed=0; failed=0; skipped=0

usage() {
  echo "usage: chaos.sh --profile <lite|standard|full> --this-install-is-disposable [--fault <browser|connector|provider|worker|db>]... [--recover-within SECONDS]" >&2
}

while test "$#" -gt 0; do
  case "$1" in
    --profile) BRAIN_PROFILE="${2:-}"; shift 2 ;;
    --fault) WANTED="$WANTED ${2:-}"; shift 2 ;;
    --recover-within) RECOVER_WITHIN="${2:-}"; shift 2 ;;
    --this-install-is-disposable) DISPOSABLE=yes; shift ;;
    *) usage; echo "unknown option: $1" >&2; exit 2 ;;
  esac
done

if test "$DISPOSABLE" != yes; then
  usage
  echo "this stops real services of a running install, so it does nothing until it is told the install may be broken on purpose with --this-install-is-disposable" >&2
  exit 2
fi

case "$BRAIN_PROFILE" in
  lite) BRAIN_COMPOSE_FILES="-f /opt/brain/docker-compose.lite.yml" ;;
  standard) BRAIN_COMPOSE_FILES="-f /opt/brain/docker-compose.yml -f /opt/brain/docker-compose.worker.yml -f /opt/brain/docker-compose.parse-worker.yml -f /opt/brain/docker-compose.objectstore.yml -f /opt/brain/docker-compose.keycloak.yml -f /opt/brain/docker-compose.presidio.yml" ;;
  full) BRAIN_COMPOSE_FILES="-f /opt/brain/docker-compose.yml -f /opt/brain/docker-compose.worker.yml -f /opt/brain/docker-compose.parse-worker.yml -f /opt/brain/docker-compose.objectstore.yml -f /opt/brain/docker-compose.keycloak.yml -f /opt/brain/docker-compose.langfuse.yml -f /opt/brain/docker-compose.automation.yml -f /opt/brain/docker-compose.matcher.yml -f /opt/brain/docker-compose.presidio.yml" ;;
  *) usage; echo "--profile is required, and one of: lite standard full" >&2; exit 2 ;;
esac

case "$RECOVER_WITHIN" in
  ""|*[!0-9]*|0) usage; echo "--recover-within is a whole number of seconds, at least 1" >&2; exit 2 ;;
esac

test -n "$WANTED" || WANTED=" browser connector provider worker db"
for one in $WANTED; do
  case "$one" in
    browser|connector|provider|worker|db) ;;
    *) usage; echo "unknown fault: $one; the faults are: browser connector provider worker db" >&2; exit 2 ;;
  esac
done

load_fault() {
  case "$1" in
    browser)
      F_SERVICE=''; F_LABEL=brain.browser.run
      F_DOWN=recorded
      F_PRESENTS='a browsing run ends without its result, and its sandbox containers are left behind carrying the run label until the launcher sweeps them at its next start'
      F_RESPONSE='see ops/browser/REHEARSAL.md; the launcher removes everything carrying the run label at its next start'
      F_FOLLOW='start a browsing task, kill its containers again, then start another and confirm the first is shown as ended and its leftovers are gone'
      F_WHY_SKIPPED='no browsing run was in flight, so there is nothing to kill'
      ;;
    connector)
      F_SERVICE=automation-egress; F_LABEL=''
      F_DOWN=recorded
      F_PRESENTS='flows that call a connector fail at the call, with a refused or unreachable proxy; the editor still opens, because the canvas itself is up'
      F_RESPONSE='the proxy is the only route out and the canvas has no other, so a flow fails closed rather than reaching an address nobody allowed; a step that may have reached its source before the failure is resumed from the operation record, as for the canvas'
      F_FOLLOW='run a flow that calls a connector while the proxy is stopped, then confirm the step failed closed and that the operation record, not the canvas, says whether it reached its source'
      F_WHY_SKIPPED='the egress proxy runs only in the full profile'
      ;;
    provider)
      F_SERVICE=inference-server; F_LABEL=''
      F_DOWN=recorded
      F_PRESENTS='two thirds of requests fail against a listening socket; the container is green in every view that checks liveness'
      F_RESPONSE='readiness probes every model in brain.ops.inference.SERVED_MODELS rather than the process, and the memory limit is arithmetic over the weights rather than what was left over'
      F_FOLLOW='ask a question while the model server is stopped and confirm the answer falls to the next step of the ladder or says plainly that it could not be composed, and that the Models screen shows the step as unhealthy afterwards'
      F_WHY_SKIPPED='the model server is started by its own compose file, which an install may not have added'
      ;;
    worker)
      F_SERVICE=brain-worker; F_LABEL=''
      F_DOWN=recorded
      F_PRESENTS='nothing at all from outside. Work is accepted, queued, and never runs, which looks identical to a system with nothing to do'
      F_RESPONSE='the record decides, not the worker: brain.ops.idempotency.resume issues only from PENDING and everything else is verified against the source'
      F_FOLLOW='queue a job, stop the worker before it finishes, start it again, and confirm the job was put back only if its task is declared safe, and set aside for a person if not'
      F_WHY_SKIPPED='the worker runs in the standard and full profiles'
      ;;
    db)
      F_SERVICE=db; F_LABEL=''
      F_DOWN=not-ready
      F_PRESENTS='readiness fails; out of connections presents as intermittent failure under load and nothing at all when it is quiet'
      F_RESPONSE='brain.ops.connections holds the ceiling arithmetic and its headroom figure is what a restore, a migration or a diagnosis has to fit in; a full disk is the host row and is not the same fault'
      F_FOLLOW='confirm no request was answered from the cache while the database was down, and that nothing written during the outage is missing or doubled afterwards'
      F_WHY_SKIPPED='the database is in every profile, so this is an install that is not up'
      ;;
  esac
}

cd "$BRAIN_HOME" || { echo "cannot enter $BRAIN_HOME" >&2; exit 2; }

probe() {
  docker compose $BRAIN_COMPOSE_FILES exec -T app python - "$1" 2>/dev/null <<'PY' || echo 0
import sys, urllib.error, urllib.request
try:
    print(urllib.request.urlopen("http://127.0.0.1:8000" + sys.argv[1], timeout=4).status)
except urllib.error.HTTPError as error:
    print(error.code)
except Exception:
    print(0)
PY
}

start_again() {
  if test -n "$CURRENT_IDS"; then
    docker start $CURRENT_IDS >/dev/null 2>&1
    CURRENT_IDS=""
  fi
}
trap start_again EXIT
trap 'exit 130' INT TERM HUP

run_fault() {
  load_fault "$1"
  echo "== $1"
  echo "   A real outage presents as: $F_PRESENTS"
  echo "   What to do about it: $F_RESPONSE"
  if test -n "$F_SERVICE"; then
    ids="$(docker ps -q --filter "label=com.docker.compose.project=$PROJECT" --filter "label=com.docker.compose.service=$F_SERVICE")"
  else
    ids="$(docker ps -q --filter "label=$F_LABEL")"
  fi
  if test -z "$ids"; then
    echo "   SKIPPED: no running container to stop ($F_WHY_SKIPPED)"
    skipped=$((skipped + 1))
    return
  fi
  if test -n "$F_SERVICE"; then
    CURRENT_IDS="$ids"
    docker stop $ids >/dev/null 2>&1 \
      || { echo "   NOT RUN: it could not be stopped"; failed=$((failed + 1)); return; }
  else
    docker kill $ids >/dev/null 2>&1 \
      || { echo "   NOT RUN: the containers could not be killed"; failed=$((failed + 1)); return; }
  fi
  ran=$((ran + 1))
  verdict=ok
  live="$(probe /health/live)"
  ready="$(probe /health/ready)"
  if test "$F_DOWN" = not-ready; then
    started=$SECONDS
    while test "$ready" = 200 && test $((SECONDS - started)) -lt "$DOWN_WAIT"; do
      sleep "$POLL_SECONDS"
      ready="$(probe /health/ready)"
    done
    if test "$ready" = 200; then
      echo "   FAILED: readiness still said ready after ${DOWN_WAIT}s with it stopped"
      verdict=failed
    fi
  fi
  echo "   while down: liveness $live, readiness $ready"
  if test "$live" != 200; then
    echo "   FAILED: the application stopped answering liveness while it was down"
    verdict=failed
  fi
  if test -n "$F_SERVICE"; then
    docker start $ids >/dev/null 2>&1 \
      || echo "   could not start it again; start it by hand"
    CURRENT_IDS=""
  fi
  started=$SECONDS
  ready="$(probe /health/ready)"
  while test "$ready" != 200 && test $((SECONDS - started)) -lt "$RECOVER_WITHIN"; do
    sleep "$POLL_SECONDS"
    ready="$(probe /health/ready)"
  done
  if test "$ready" = 200; then
    echo "   recovered: ready again after $((SECONDS - started))s (limit ${RECOVER_WITHIN}s)"
  else
    echo "   FAILED: not ready ${RECOVER_WITHIN}s after it was started again"
    verdict=failed
  fi
  echo "   Check by hand: $F_FOLLOW"
  if test "$verdict" = ok; then
    passed=$((passed + 1))
  else
    failed=$((failed + 1))
  fi
}

app_id="$(docker compose $BRAIN_COMPOSE_FILES ps -q app 2>/dev/null)"
PROJECT="$(docker inspect -f '{{index .Config.Labels "com.docker.compose.project"}}' "$app_id" 2>/dev/null)"
if test -z "$app_id" || test -z "$PROJECT"; then
  echo "the application container of this profile is not found, so which compose project this install is cannot be told, and nothing is stopped" >&2
  exit 1
fi
live="$(probe /health/live)"; ready="$(probe /health/ready)"
if test "$live" != 200 || test "$ready" != 200; then
  echo "the application is not live and ready before any fault (liveness $live, readiness $ready), so a fault would teach nothing" >&2
  exit 1
fi

for one in $WANTED; do
  run_fault "$one"
done

echo ""
echo "ran $ran: $passed passed, $failed failed; $skipped skipped"
if test "$failed" -gt 0; then
  exit 1
fi
if test "$ran" -eq 0; then
  echo "nothing was run, so nothing is shown" >&2
  exit 3
fi
exit 0
